begin;
create or replace function pg_temp.expect(ok boolean,label text) returns void language plpgsql as $$begin if not coalesce(ok,false) then raise exception 'LP TEST: %',label;end if;end$$;
create or replace function pg_temp.denied(q text) returns boolean language plpgsql as $$begin execute q;return false;exception when insufficient_privilege then return true;end$$;
create or replace function pg_temp.rejected(q text) returns boolean language plpgsql as $$begin execute q;return false;exception when others then return true;end$$;
insert into public.app_members(email) values('lp.one@fund.test'),('lp.two@fund.test'),('lp.admin@fund.test');
insert into public.member_permissions(email,permission) values('lp.one@fund.test','lp_scouting'),('lp.one@fund.test','portfolio'),('lp.admin@fund.test','admin');
insert into public.google_mailbox_connections(email,refresh_token_encrypted,refresh_token_iv,refresh_token_tag) values('lp.one@fund.test','synthetic','synthetic','synthetic');
insert into public.capital_events(id,event_type,event_date,amount) values('fc000000-0000-0000-0000-000000000001','wire_in','2026-09-01',123.45);
create temp table fixture(key text primary key,id uuid,lease uuid);grant all on fixture to authenticated,vanquish_worker;
create temp table people_before_scan as select count(*) value from public.people;grant select on people_before_scan to authenticated;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"lp.two@fund.test"}',true);
select pg_temp.expect(pg_temp.denied('select public.configure_lp_scouting(true,''auto'',false,30,100)'),'permissionless scan denied');
select pg_temp.expect(pg_temp.denied('select public.save_lp_record(''fund'',''{"name":"Hidden","currency":"USD"}'')'),'permissionless financial write denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"lp.one@fund.test"}',true);
select public.configure_lp_scouting(true,'auto',false,30,100);select public.request_lp_scan();select public.request_lp_scan();
select pg_temp.expect((select count(*)=2 from public.lp_scout_jobs where status='pending'),'queue deduplicates each service');
select pg_temp.expect(pg_temp.denied('update public.lp_scouting_settings set enabled=false'),'consent cannot bypass RPC');
insert into fixture select 'lease',id,lease from public.claim_my_lp_scan() limit 1;
select public.commit_my_lp_scan((select id from fixture where key='lease'),(select lease from fixture where key='lease'),case (select service from public.lp_scout_jobs where id=(select id from fixture where key='lease')) when 'gmail' then '[{"id":"out","threadId":"t","at":"2026-10-01","email":"ana@outside.test","name":"Ana","direction":"outbound","strong":true,"metadata":"Private subject","body":"never stored"},{"id":"reply","threadId":"t","at":"2026-10-02","email":"ana@outside.test","name":"Ana","direction":"reply"},{"id":"unrelated","threadId":"other","at":"2026-10-01","email":"founder@startup.test","direction":"reply"}]'::jsonb else '[{"id":"meeting","threadId":"m","at":"2026-10-01","email":"ana@outside.test","name":"Ana","direction":"meeting","strong":true,"metadata":"Private title"}]'::jsonb end,'{}',true);
select pg_temp.expect((select count(*)=1 from public.lp_suggestions),'only qualifying contacts suggested');
select pg_temp.expect((select count(*) from public.people)=(select value from people_before_scan),'scanning publishes no People before human approval');
select pg_temp.expect((select confidence='high' and evidence::text not like '%Private%' and evidence::text not like '%never stored%' from public.lp_suggestions),'independent metadata consent and body exclusion');
insert into fixture select 'suggestion',id,null from public.lp_suggestions limit 1;
insert into fixture values('person',public.decide_lp_suggestion((select id from fixture where key='suggestion'),true,'Ana',true,null),null);
select pg_temp.expect((select count(*)=1 from public.lp_board_cards),'accept creates one explicit own-board card');
select pg_temp.expect(public.decide_lp_suggestion((select id from fixture where key='suggestion'),true,'Ana',true,null)=(select id from fixture where key='person'),'accept retries are idempotent');
select pg_temp.expect((select count(*)=1 from public.lp_board_cards),'repeat accept never duplicates card');
insert into fixture values('investor',public.save_lp_record('investor',jsonb_build_object('personId',(select id from fixture where key='person'),'name','Synthetic LP')),null);
insert into fixture values('fund',public.save_lp_record('fund','{"name":"Synthetic Fund","currency":"USD","target":"1000000"}'),null);
insert into fixture values('pipeline',public.save_lp_record('pipeline',jsonb_build_object('investorId',(select id from fixture where key='investor'),'fundId',(select id from fixture where key='fund'),'stage','prospect')),null);
select public.save_lp_record('pipeline',jsonb_build_object('investorId',(select id from fixture where key='investor'),'fundId',(select id from fixture where key='fund'),'stage','interest','expectedStage','prospect'));
select pg_temp.expect((select count(*)=2 from public.lp_stage_history),'immutable stage history appended');
select pg_temp.expect(pg_temp.rejected(format('select public.save_lp_record(''pipeline'',%L)',jsonb_build_object('investorId',(select id from fixture where key='investor'),'fundId',(select id from fixture where key='fund'),'stage','closed','expectedStage','prospect'))),'stale stage conflicts');
select pg_temp.expect(pg_temp.rejected(format('select public.save_lp_record(''pipeline'',%L)',jsonb_build_object('investorId',(select id from fixture where key='investor'),'fundId',(select id from fixture where key='fund'),'stage','lost','expectedStage','interest'))),'lost requires a reason');
select public.save_lp_record('commitment',jsonb_build_object('investorId',(select id from fixture where key='investor'),'fundId',(select id from fixture where key='fund'),'amount','50000','date','2026-10-01','status','signed'));
select public.save_lp_record('flow',jsonb_build_object('id','fa000000-0000-0000-0000-000000000001','investorId',(select id from fixture where key='investor'),'fundId',(select id from fixture where key='fund'),'amount','10000','date','2026-10-02','flowKind','contribution'));
select public.save_lp_record('flow',jsonb_build_object('id','fa000000-0000-0000-0000-000000000001','investorId',(select id from fixture where key='investor'),'fundId',(select id from fixture where key='fund'),'amount','10000','date','2026-10-02','flowKind','contribution'));
select pg_temp.expect((select event_type='wire_in' and fundraising_fund_id is null and flow_currency is null and lp_flow_kind is null and amount=123.45 from public.capital_events where id='fc000000-0000-0000-0000-000000000001'),'historical wire preserved without inferred classification');
select pg_temp.expect((select count(*)=1 from public.capital_events where fundraising_fund_id=(select id from fixture where key='fund')),'flow retries do not duplicate accounting');
select pg_temp.expect(pg_temp.rejected(format('select public.save_lp_record(''fund'',%L)',jsonb_build_object('id',(select id from fixture where key='fund'),'name','Fund','currency','EUR'))),'used fund currency cannot change');
select public.save_lp_record('preferences',jsonb_build_object('investorId',(select id from fixture where key='investor'),'reportFrequency','quarterly','contactPreference','ask','coInvestment',true,'notes','Private preferences'));
select public.save_lp_record('task',jsonb_build_object('investorId',(select id from fixture where key='investor'),'title','Private follow-up'));
select public.save_lp_record('board_link',jsonb_build_object('investorId',(select id from fixture where key='investor'),'cardId',(select id from public.lp_board_cards limit 1)));
select set_config('request.jwt.claims','{"role":"authenticated","email":"lp.two@fund.test"}',true);
select pg_temp.expect((select count(*)=0 from public.lp_suggestions),'private suggestions isolated');
select pg_temp.expect((select count(*)=0 from public.lp_commitments),'financial rows hidden without portfolio');
select pg_temp.expect((select count(*)=0 from public.lp_board_investor_links),'canonical board links do not reveal private data');
select pg_temp.expect(pg_temp.denied(format('select public.decide_lp_suggestion(%L,true,''Guess'',false,null)',(select id from fixture where key='suggestion'))),'other-member accept denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"lp.admin@fund.test"}',true);
select pg_temp.expect(not exists(select 1 from public.audit_log where entity_table='lp_commitments'),'Admin without Portfolio cannot inspect financial audit snapshots');
select public.admin_set_member_permission('lp.admin@fund.test','portfolio',true);
select pg_temp.expect(exists(select 1 from public.audit_log where entity_table='lp_commitments'),'Portfolio Admin can inspect financial audit');
select pg_temp.expect(not exists(select 1 from public.audit_log where entity_table='lp_board_investor_links'),'Portfolio Admin cannot inspect another private board link audit');
select id,display_name,person_id,company_id from public.investors limit 1;
select id,name,currency,target_amount,legal_entity_id from public.fundraising_funds limit 1;
select id,name from public.people limit 1;
select id,investor_id,fundraising_fund_id,flow_currency,lp_flow_kind,amount,event_date from public.capital_events limit 1;
select id,investor_id,title,due_date,done,assignee_email from public.lp_tasks limit 1;
select public.admin_set_member_permission('lp.one@fund.test','lp_scouting',false);
reset role;truncate fixture;
update public.lp_scout_jobs set status='running',lease='fb000000-0000-0000-0000-000000000001',locked_until=now()+interval '5 minutes' where service='gmail';
insert into fixture select 'revoked',id,lease from public.lp_scout_jobs where service='gmail';
set local role vanquish_worker;
select pg_temp.expect(pg_temp.denied(format('select public.worker_commit_lp_scan(%L,%L,''[]'',''{}'',true)',(select id from fixture),(select lease from fixture))),'revoked permission invalidates worker publication');
select pg_temp.expect(pg_temp.denied('select * from private.lp_scout_evidence'),'no direct machine evidence access');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","email":"not-member@fund.test"}',true);
select pg_temp.expect(pg_temp.denied('select public.request_lp_scan()'),'nonmember denied');
select set_config('request.jwt.claims','{"role":"authenticated","email":"lp.one@fund.test"}',true);
select public.disconnect_and_withdraw_sync();
reset role;
select pg_temp.expect(not exists(select 1 from private.lp_scout_evidence where member_email='lp.one@fund.test'),'withdraw removes source evidence');
select pg_temp.expect(not exists(select 1 from public.lp_scout_jobs where member_email='lp.one@fund.test'),'withdraw removes leases/cursors');
select pg_temp.expect((select status='accepted' and evidence='[]' from public.lp_suggestions where member_email='lp.one@fund.test'),'terminal decision retained without source metadata');
select pg_temp.expect(exists(select 1 from public.lp_commitments),'explicit manual commitments survive Google withdrawal');
select pg_temp.expect(not has_function_privilege('anon','public.save_lp_record(text,jsonb)','execute'),'anon cannot access financial RPC');
rollback;
